export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioResults {
  results: unknown[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

const itemPremium = (item: Item): number =>
  BASE_PREMIUMS[item.type] * (1 + FIRST_INSURANCE_SURCHARGE);

const quotePremium = (step: QuoteStep): number => {
  const policyBasePremium = step.items.reduce(
    (sum, item) => sum + itemPremium(item),
    0,
  );

  return roundUp(policyBasePremium + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});

