const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const COMPONENT_TYPES = ["rune", "moonstone"];
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();

  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  return counts;
};

/**
 * Alike components form a building block at the special premium, but only
 * when there are exactly BLOCK_SIZE of them.
 */
const componentsBasePremium = (items: Item[]): number => {
  let total = 0;

  for (const [type, count] of countByType(items)) {
    total +=
      count === BLOCK_SIZE
        ? BLOCK_BASE_PREMIUM
        : count * BASE_PREMIUMS[type];
  }

  return total;
};

/** The policy base premium is the sum of the base premiums of its items. */
const policyBasePremium = (items: Item[]): number => {
  const mainItems = items.filter((item) => !isComponent(item));
  const components = items.filter(isComponent);

  return (
    mainItems.reduce((sum, item) => sum + itemBasePremium(item), 0) +
    componentsBasePremium(components)
  );
};

