import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case and base premiums ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });
  it("a sword → base premium 100 G, +10 % first insurance, +5 G fee → premium 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("an amulet → base premium 60 G, +10 % first insurance, +5 G fee → premium 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("a staff → base premium 80 G, +10 % first insurance, +5 G fee → premium 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("a potion → base premium 40 G, +10 % first insurance, +5 G fee → premium 49 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });
  it("a single rune → base premium 25 G, +10 % first insurance, +5 G fee → premium 33 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it("a single moonstone → base premium 25 G, +10 % first insurance, +5 G fee → premium 33 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 33 }] });
  });

  // --- Building block of 3 alike components ---
  it("2 runes → 50 G base premium (no block) → premium 60 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes → 60 G base premium (block applies) → premium 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes → 100 G base premium (no block — block requires exactly 3) → premium 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes → 175 G base premium (no block) → premium 198 G (197.5 rounded up)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 198 }] });
  });

  // --- "Alike" components: same type, not same family ---
  it("2 runes + 1 moonstone → 75 G base premium (no block: different types) → premium 88 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks) → premium 137 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
            { type: "moonstone" },
            { type: "moonstone" },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Item-specific modifiers ---
  it("a cursed sword adds a 50 % risk surcharge → 100 base + 50 curse + 10 first insurance + 5 fee = 165 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: true }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 165 }] });
  });
  it.todo("a sword with enchantment 5 adds a 30 % surcharge → base 100 G + 30 G");
  it.todo("a sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("a cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30)");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance carries a 10 % initial assessment surcharge");
  it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
  it.todo("the third quote in a scenario also receives the 15 % follow-up contract discount");
  it.todo(
    "each item in a quote is treated as a first insurance regardless of customer history — the 10 % surcharge applies on a follow-up contract too",
  );

  // --- Modifier scope on multi-item policies ---
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
  );
  it.todo(
    "policy-wide modifiers apply to the policy base premium (sum of item base premiums), the processing fee is added at the very end",
  );

  // --- Rounding in the MHPCO's favour ---
  // "a premium calculation that yields 197.5 G → final premium 198 G (rounded up)"
  // is covered by the 7-runes test above, which yields exactly 197.5 G.
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Claim: standard reimbursement ---
  it.todo(
    "regular sword (steel, enchantment 3), damage 500 G → payout 400 G (full reimbursement minus 100 G deductible)",
  );
  it.todo(
    "damage to a rune (no enchantment level or material), damage 200 G → payout 100 G (full reimbursement minus deductible)",
  );

  // --- Claim: special clauses ---
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo(
    "dragon-material sword, enchantment 5, damage 800 G → payout 700 G (dragon clause: full reimbursement, then deductible)",
  );
  it.todo(
    "dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies, then deductible)",
  );
  it.todo(
    "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (both clauses apply; the 50 % rule wins, then deductible)",
  );

  // --- Deductible per damage event ---
  it.todo(
    "a dragon attack damages an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible applies once per damaged item)",
  );

  // --- Cap ---
  it.todo("a policy covers a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo(
    "a cursed sword (premium with modifiers 165 G) → cap 2000 G (based on the unmodified insurance value)",
  );
  it.todo(
    "a policy covers a sword and 3 runes (a block) → insurance sum 1750 G; the block discount affects the premium only",
  );
  it.todo(
    "sword insured (cap 2000 G), two successive claims of 1500 G each → first claim payout 1400 G, remainingCap 600 G",
  );
  it.todo(
    "second successive claim of 1500 G → payout 600 G (reduced to the remaining cap), remainingCap 0 G",
  );

  // --- Multiple items of the same type ---
  it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
  it.todo(
    "a dragon attack damages both swords (two sword damage entries) → each entry is a separate damage with its own deductible",
  );
  it.todo(
    "more damage entries of a type than the policy covers (two sword damages, one sword insured) → the whole claim is rejected with an error",
  );

  // --- Error cases ---
  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
  it.todo("claim references a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) → error");
  it.todo("claim references a damage entry with an unknown item type → error");
  it.todo("claim contains a damage entry with amount -200 → error");

  // --- Integration examples ---
  it.todo(
    "newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G",
  );
  it.todo(
    "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
  );

  // --- Scenario / results shape ---
  it.todo("results array has the same length and order as the input steps");
  it.todo("a claim step refers to the policy created by an earlier quote step via its zero-based step index");
});

